if (!customElements.get('recently-viewed')) {
    customElements.define('product-recently-viewed', class RecentlyViewed extends HTMLElement {
        constructor() {
            super();
            this.viewed_products =JSON.parse(localStorage.getItem('ViewedProductsShihiko'));
            this.url = this.dataset.url;
            if(localStorage.getItem('ViewedProductsShihiko') ){
                this.updateProductList();
                this.renderBlock();

            }else{
                this.addProductList();
            }
        }
        renderBlock() {
            if(this.viewed_products){
				const _this = this;
                let productList = this.viewed_products.join(',');
                let template = Math.random();
                fetch(`${this.url}?section_id=ajax-product-recently-viewed&view=template-${template}&products=${productList}&end-products`)
                    .then((response) => {
                        return response.text();
                    })
                    .then((response_html) => {
                        const html = new DOMParser().parseFromString(response_html, 'text/html')
                        const fetchProductList = html.querySelector('#product-list');
                        const productList = this.querySelector('[data-product-list]');
                        if(fetchProductList && productList){
                            productList.innerHTML = fetchProductList.innerHTML;
                            if(window.lazyLoadEnabled == "true"){
                                reloadLazyLoad();
                            }
                            if(fetchProductList){
                                if(fetchProductList.innerHTML.trim() != ''){
									_this.initSlider();
									_this.removeAttribute('style');
									reloadProductCardHover();

                                    const recentlyEvent = new CustomEvent('recently-viewed-loaded');
                                    document.dispatchEvent(recentlyEvent)
                                }
                            }
                        }              
                    }) .catch((e) => {
                    console.error(e);
                });
            }
        }
        updateProductList(){
            if(this.dataset.handle){
                let viewed_products =JSON.parse(localStorage.getItem('ViewedProductsShihiko'));
                if(viewed_products.includes(`${this.dataset.handle}`)){
                    viewed_products.splice(viewed_products.indexOf(`${this.dataset.handle}`), 1);
                }
                viewed_products.unshift(`${this.dataset.handle}`)
                viewed_products = viewed_products.slice(0,12)
                localStorage.setItem('ViewedProductsShihiko', JSON.stringify(viewed_products));
            }
        }
        addProductList(){
            if(this.dataset.handle) {
                let viewed_products = [`${this.dataset.handle}`];
                localStorage.setItem('ViewedProductsShihiko', JSON.stringify(viewed_products));
            }
        }
		initSlider(){
			if(this.querySelector('.product-list__slider')){
				let sliderScrollbar = this.querySelector('.swiper-scrollbar');
				const productListSwiper = new Swiper(this.querySelector('.product-list__slider'), {
					slidesPerView: 3,
					paginationClickable: true,
					spaceBetween: 4,
					freeMode: true,
					scrollbar: {
						el: sliderScrollbar,
						draggable: true
					},
					breakpoints: {
						1025: {
							slidesPerView: 4
						},
						768: {
							slidesPerView: 3
						},
						325: {
							slidesPerView: 2
						},
						300: {
							slidesPerView: 2
						}
					}
				});
			}

		}
    });
}
